3	import * as React from "react";
4	import { useTransition } from "react";
5	import { Heart } from "lucide-react";
6	import { addFavorite, removeFavorite } from "@/app/(customer)/account/actions";
7	import { t } from "@/lib/i18n";
8	import { useToast } from "@/components/ui/Toast";
9	
10	/**
11	 * Heart toggle to save/remove a listener. Keyboard-operable, state via
12	 * aria-pressed (text label in aria-label, never colour alone), announced.
13	 */
14	export function FavoriteButton({
15	  providerId,
16	  providerName,
17	  initialFavorite,
18	}: {
19	  providerId: string;
20	  providerName: string;
21	  initialFavorite: boolean;
22	}) {
23	  const [favorite, setFavorite] = React.useState(initialFavorite);
24	  const [pending, startTransition] = useTransition();
25	  const { announce } = useToast();
26	
27	  function toggle() {
28	    const next = !favorite;
29	    setFavorite(next);
30	    startTransition(async () => {
31	      const res = next
32	        ? await addFavorite(providerId)
33	        : await removeFavorite(providerId);
34	      if (!res.ok) {
35	        setFavorite(!next); // revert
36	        return;
37	      }
38	      announce(
39	        next
40	          ? t("favorite.added", { name: providerName })
41	          : t("favorite.removed", { name: providerName }),
42	      );
43	    });
44	  }
45	
46	  return (
47	    <button
48	      type="button"
49	      onClick={toggle}
50	      disabled={pending}
51	      aria-pressed={favorite}
52	      aria-label={
53	        favorite
54	          ? t("favorite.remove", { name: providerName })
55	          : t("favorite.add", { name: providerName })
56	      }
57	      className="inline-flex size-11 items-center justify-center rounded-pill border border-border-strong bg-surface text-ink-soft hover:bg-primary-tint/50 aria-pressed:border-accent aria-pressed:text-accent"
58	    >
59	      <Heart
60	        size={20}
61	        strokeWidth={2}
62	        aria-hidden="true"
63	        className={favorite ? "fill-accent" : ""}
64	      />
65	    </button>
66	  );
67	}
